from datetime import datetime
from decimal import Decimal, InvalidOperation

from .models import Transaction
from .rows import split_fields

COLUMNS = ('date', 'payee', 'memo', 'amount')


class RowError(Exception):
    def __init__(self, number, message):
        super().__init__(f'row {number}: {message}')


def import_lines(lines):
    result = []
    for number, line in enumerate(lines[1:], start=2):
        if not line.strip():
            continue
        fields = split_fields(line)
        if len(fields) != len(COLUMNS):
            raise RowError(number, f'expected {len(COLUMNS)} columns, got {len(fields)}')
        date, payee, memo, amount = fields
        try:
            when = datetime.strptime(date, '%Y-%m-%d').date()
            result.append(Transaction(when, payee, memo, Decimal(amount)))
        except (ValueError, InvalidOperation) as exc:
            raise RowError(number, str(exc))
    return result
